async function initialisePython(onStatusChange = () => {}) {

    try {
        onStatusChange("Loading Python...");

        const pyodide = await loadPyodide();

        await pyodide.loadPackage("micropip");

        const micropip = pyodide.pyimport("micropip");

        // Discover the wheel generated by GitHub Actions
        const manifestResponse = await fetch(
            "./dist/manifest.json",
            { cache: "no-store" }
        );

        if (!manifestResponse.ok) {
            throw new Error(
                `Failed to load manifest: ${manifestResponse.status}`
            );
        }

        const manifest = await manifestResponse.json();

        // Resolve the wheel's location
        const wheelUrl = new URL(
            `./dist/${manifest.wheel}`,
            document.baseURI
        ).href;

        // Install Python package
        onStatusChange("Installing game package...");

        await micropip.install(wheelUrl);

        // Execute Python integration test
        const result = pyodide.runPython(`
            from onwords.test import test_python
            test_python()
        `);

        onStatusChange("Python ready");
        return pyodide;

    } catch (error) {
        console.error("Python initialisation failed:", error);
        throw error;
    }
}

let pythonPromise = null;

export function getPython(onStatusChange) {
    if (pythonPromise === null) {
        pythonPromise = initialisePython(onStatusChange);
    }

    return pythonPromise;
}